        """Return the Wikipedia URL and language, preferring the requested language."""
        for candidate_language in dict.fromkeys((language, 'en')):
            sitelink = self.sitelinks.get(f'{candidate_language}wiki')
            if isinstance(sitelink, dict):
                url = sitelink.get('url')
                if isinstance(url, str) and url:
